import React, { useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, Select, MenuItem, InputLabel, FormHelperText, } from '@mui/material';
import { yupResolver } from '@hookform/resolvers/yup';
import { useForm, Controller } from 'react-hook-form';
import * as yup from 'yup';
import Iconify from '../../components/iconify';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import InputField from '../../components/input/inputField';
// import InputField from '../../components/input/ReactHookForm/inputField';
import useResponsive from '../../hooks/useResponsive';
import { axios } from '../../utils/axios';

const packagesSchema = yup.object().shape({
  packageName: yup.string().required('Package Name is required'),
  description: yup.string().required('Description is required'),
  price: yup.number().typeError('Price must be a number').required('Price is required'),
  currency: yup.string().required('Currency is required'),
  adsLimit: yup.number().typeError('Ads Limit must be a number').required('Ads Limit is required'),
  validityDays: yup.number().typeError('Validity Days must be a number').required('Validity Days are required'),
  type: yup.string().required('Package Type is required'),
});

const PackagesForm = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const subscriptionId = queryParams.get('ids') || null;
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors }
  } = useForm({
    resolver: yupResolver(packagesSchema),
    defaultValues: {
      packageName: '',
      description: '',
      price: '',
      currency: '',
      adsLimit: '',
      validityDays: '',
      type: '',
    },
  });

  useEffect(() => {
    if (subscriptionId) {
      fetchSubscriptionData();
    }
  }, [subscriptionId]);

  const fetchSubscriptionData = async () => {
    try {
      const response = await axios.get(`module/ads/packages/${subscriptionId}`);
      
      if (response?.status === 200) {
        reset(response?.data?.data?.packages?.[0] || {}); // Reset the form with fetched data
      }
    } catch (error) {
      GenerateToastConfig(error?.message);
    }
  };


  const onSubmit = async (data) => {
    try {

      const url = subscriptionId ? `module/ads/packages/${subscriptionId}` : 'module/ads/packages';
      const method = subscriptionId ? 'put' : 'post';

      const response = await axios[method](url, data);
      
      if (response?.status === (subscriptionId ? 200 : 200)) {
        GenerateToastConfig(response.data.message, 'success');
        navigate('/dashboard/packagesList');
      }
      
    } catch (error) {
      GenerateToastConfig(error.response?.data?.message || 'Error processing request');
    }
  };

  const backToGallery = () => {
    navigate('/dashboard/packagesList');
  };

  return (
    <>
      <Helmet>
        <title>{subscriptionId ? 'Edit Subscription' : 'Add Subscription'}</title>
      </Helmet>
      <Card>
        <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Box
                sx={{
                  width: '37px',
                  height: '37px',
                  background: '#FF5A60',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  cursor: 'pointer'
                }}
                onClick={backToGallery}
              >
                <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
              </Box>
              <Typography variant="h6" sx={{ marginLeft: '10px' }}>
                {subscriptionId ? i18?.ACCOUNTSTITLE?.EDIT_PACKAGE || 'Edit Package' : i18?.ACCOUNTSTITLE?.ADD_PACKAGE || 'Add Package'}
              </Typography>
            </Box>
          </Grid>
        </Grid>
        <Divider sx={{ backgroundColor: "#333", margin: "10px 0px" }} />
        <form onSubmit={handleSubmit(onSubmit)}>
          <Grid container={!isMobile} sx={{ padding: '10px 30px' }}>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
              <Controller
                name="packageName"
                control={control}
                render={({ field, fieldState }) => {
                  console.log(field);
                  return (
                    <InputField
                      {...field}
                      label="Package Name"
                      error={fieldState.error?.message}
                      required
                      sx={{
                        margin: '10px 0px',
                        width: '100%',
                        '& .MuiInputBase-input.MuiOutlinedInput-input': {
                          padding: '10.5px 14px'
                        }
                      }}
                    />
                  )
                }}
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
              <Controller
                name="description"
                control={control}
                render={({ field, fieldState }) => (
                  <InputField
                    {...field}
                    label="Description"
                    error={fieldState.error?.message}
                    required
                    sx={{
                      margin: '10px 0px',
                      width: '100%',
                      '& .MuiInputBase-input.MuiOutlinedInput-input': {
                        padding: '10.5px 14px'
                      }
                    }}
                  />
                )}
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
              <Controller
                name="price"
                control={control}
                render={({ field, fieldState }) => (
                  <InputField
                    {...field}
                    type="number"
                    label="Price"
                    error={fieldState.error?.message}
                    required
                    sx={{
                      margin: '10px 0px',
                      width: '100%',
                      '& .MuiInputBase-input.MuiOutlinedInput-input': {
                        padding: '10.5px 14px'
                      }
                    }}
                  />
                )}
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
              <Controller
                name="currency"
                control={control}
                render={({ field, fieldState }) => (
                  <InputField
                    {...field}
                    label="Currency"
                    error={fieldState.error?.message}
                    required
                    sx={{
                      margin: '10px 0px',
                      width: '100%',
                      '& .MuiInputBase-input.MuiOutlinedInput-input': {
                        padding: '10.5px 14px'
                      }
                    }}
                  />
                )}
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
              <Controller
                name="adsLimit"
                control={control}
                render={({ field, fieldState }) => (
                  <InputField
                    {...field}
                    type="number"
                    label="Ads Limit"
                    error={fieldState.error?.message}
                    required
                    sx={{
                      margin: '10px 0px',
                      width: '100%',
                      '& .MuiInputBase-input.MuiOutlinedInput-input': {
                        padding: '10.5px 14px'
                      }
                    }}
                  />
                )}
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
              <Controller
                name="validityDays"
                control={control}
                render={({ field, fieldState }) => (
                  <InputField
                    {...field}
                    label="Validity Days"
                    error={fieldState.error?.message}
                    required
                    sx={{
                      margin: '10px 0px',
                      width: '100%',
                      '& .MuiInputBase-input.MuiOutlinedInput-input': {
                        padding: '10.5px 14px'
                      }
                    }}
                  />
                )}
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
              <InputLabel sx={{ color: "#2B3343" }} id="category-select-label">
                {i18?.ACCOUNTSTITLE?.PACAKGE_TYPE || "Package Type"}
              </InputLabel>
              <Controller
                name="type"
                control={control}
                render={({ field, fieldState }) => (
                  <Select
                    {...field}
                    name='type'
                    error={fieldState.error?.message}
                    required
                    sx={{
                      margin: '10px 0px',
                      width: '100%',
                      '& .MuiInputBase-input.MuiOutlinedInput-input': {
                        padding: '10.5px 14px'
                      }
                    }}
                  >
                    <MenuItem value="standard">Standard</MenuItem>
                    <MenuItem value="featured">Featured</MenuItem>
                    <MenuItem value="Boosted">Boosted</MenuItem>
                  </Select>
                )}
              />
            </Grid>
          </Grid>
          <Grid container justifyContent="flex-end" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
            <Button
              sx={{
                padding: "10px 58px 10px 58px"
              }}
              variant="contained"
              type="submit"
            >
              {subscriptionId ? i18?.ACCOUNTSTITLE?.UPDATE || "Update" : i18?.ACCOUNTSTITLE?.ADD || "Add"}
            </Button>
          </Grid>
        </form>
      </Card>
    </>
  )
}

export default PackagesForm
